<template><AccountLayout bare><main class="an"><header><h1>Notifications</h1><div>Account Number: AC-{{String(authState.user?.id||0).padStart(6,'0')}}<small>Last Updated: {{date(settings.updated_at)}}</small></div></header><section><h2>1. Notification Delivery</h2><div class="delivery"><label>✉ <b>Email</b><span>{{authState.user?.email}}</span><Toggle v-model="settings.email_enabled"/></label><label>⌕ <b>Phone</b><span>{{authState.user?.phone||'Not set'}}</span><Toggle v-model="settings.phone_enabled"/></label><label>♧ <b>In-App</b><span>My Account</span><Toggle v-model="settings.in_app_enabled"/></label></div></section><section><h2>2. Notification Recipients</h2><table><thead><tr><th rowspan="2">Recipient</th><th colspan="2">Email</th><th colspan="2">Phone</th><th>In-App</th></tr><tr><th>Email Address</th><th>On / Off</th><th>Ph. No.</th><th>On / Off</th><th>On / Off</th></tr></thead><tbody><tr v-for="r in settings.recipients" :key="r.name"><td>{{r.name}}</td><td><input v-model="r.email" type="email"></td><td><Toggle v-model="r.email_enabled"/></td><td><input v-model="r.phone"></td><td><Toggle v-model="r.phone_enabled"/></td><td><Toggle v-model="r.in_app_enabled"/></td></tr></tbody></table></section><section><h2>3. Notification Preferences</h2><table class="prefs"><thead><tr><th>Notification Type</th><th>Email</th><th>Phone</th><th>In-App</th></tr></thead><tbody><tr v-for="p in settings.preferences" :key="p.key"><td>{{p.label}}</td><td><Toggle v-model="p.email"/></td><td><Toggle v-model="p.phone"/></td><td><Toggle v-model="p.in_app"/></td></tr></tbody></table><footer><button @click="load">Cancel</button><button class="save" @click="save">Save Changes</button></footer></section></main></AccountLayout></template>
<script setup>import{reactive,onMounted,defineComponent,h}from'vue';import AccountLayout from'../components/AccountLayout.vue';import client from'../api/client';import{authState}from'../store/auth';const settings=reactive({recipients:[],preferences:[]});const Toggle=defineComponent({props:{modelValue:Boolean},emits:['update:modelValue'],setup(p,{emit}){return()=>h('button',{class:['toggle',{on:p.modelValue}],onClick:()=>emit('update:modelValue',!p.modelValue),type:'button'},[h('i')])}});const date=x=>x?new Intl.DateTimeFormat('en-US',{month:'long',day:'numeric',year:'numeric'}).format(new Date(x)):'Today';const load=async()=>Object.assign(settings,(await client.get('/account/notifications')).data.data);const save=async()=>Object.assign(settings,(await client.put('/account/notifications',settings)).data.data);onMounted(load)</script>
<style scoped>.an{max-width:1260px;margin:auto;padding:16px 24px;color:#061a8f}.an header{display:flex;align-items:center;gap:35px}.an h1,.an h2{margin:0;color:#fff;background:linear-gradient(100deg,#073e7c,#01225f);border-radius:6px}.an h1{flex:1;padding:3px 20px;font-size:2.3rem}.an header>div{font-size:1.05rem;text-align:right}.an header small{display:block;margin-top:6px}section{margin-top:10px;border:1px solid #d0ddeb;border-radius:6px;overflow:hidden;background:#fff}h2{padding:6px 16px;font-size:1.06rem}.delivery{display:grid;grid-template-columns:repeat(3,1fr);padding:10px}.delivery label{display:grid;grid-template-columns:42px 1fr 58px;gap:6px;align-items:center;padding:0 18px;border-right:1px solid #c9d5e7;font-size:1.05rem}.delivery span{grid-column:2;color:#111}.delivery .toggle{grid-column:3;grid-row:1/3}table{width:100%;border-collapse:collapse;text-align:center}th,td{padding:4px 10px;border:1px solid #c9d2df;font-weight:400}td:first-child{text-align:left;padding-left:18px}td input{width:100%;height:28px;border:1px solid #d4dce8;border-radius:5px}.prefs th,.prefs td{padding:1px 10px;border-width:0 0 1px}.prefs td:first-child{font-size:.9rem}.toggle{width:43px;height:23px;border:0;border-radius:20px;background:#9ba7b4;cursor:pointer}.toggle i{display:block;width:17px;height:17px;margin:3px;border-radius:50%;background:#fff;transition:.2s}.toggle.on{background:#0758ef}.toggle.on i{margin-left:23px}footer{display:flex;justify-content:flex-end;gap:20px;padding:12px}footer button{min-width:160px;padding:9px;border:1px solid #0755ed;border-radius:5px;background:#fff;color:#0642ce;font:inherit}.save{color:#fff;background:#0755ed}@media(max-width:760px){.an{padding:10px}.an header{display:block}.an header>div{text-align:left;margin:8px}.delivery{grid-template-columns:1fr}.delivery label{padding:10px;border-bottom:1px solid #ddd}section{overflow-x:auto}table{min-width:700px}}</style>
